using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using WildCat.Protocol;
using Xunit;

namespace WildCat.Tests
{
    /// <summary>
    /// The Unity SDK's copy of the protocol (unity-sdk/Assets/Backend/Plugins/Protocol) is
    /// generated by tools/sync-protocol.sh from backend/WildCat.Protocol. These tests fail when
    /// someone changed the protocol and forgot to run the script, or edited the copy by hand.
    /// </summary>
    public class ProtocolSyncTests
    {
        private const string SyncHint = "Run tools/sync-protocol.sh (or tools/sync-protocol.ps1) from the repository root.";

        private static readonly string RepoRoot = FindRepoRoot();
        private static readonly string SourceDir = Path.Combine(RepoRoot, "backend", "WildCat.Protocol");
        private static readonly string CopyDir = Path.Combine(RepoRoot, "unity-sdk", "Assets", "Backend", "Plugins", "Protocol");

        private static string FindRepoRoot()
        {
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            while (dir != null)
            {
                if (Directory.Exists(Path.Combine(dir.FullName, "backend", "WildCat.Protocol"))
                    && Directory.Exists(Path.Combine(dir.FullName, "unity-sdk")))
                    return dir.FullName;
                dir = dir.Parent;
            }
            throw new DirectoryNotFoundException("The repository root was not found above " + AppContext.BaseDirectory);
        }

        /// <summary>The source files the script copies, as paths relative to the protocol folder with forward slashes.</summary>
        private static List<string> SourceFiles()
        {
            return Directory.EnumerateFiles(SourceDir, "*.cs", SearchOption.AllDirectories)
                .Select(f => Path.GetRelativePath(SourceDir, f).Replace('\\', '/'))
                .Where(f => !f.StartsWith("ServerOnly/", StringComparison.Ordinal)
                            && !f.StartsWith("obj/", StringComparison.Ordinal)
                            && !f.StartsWith("bin/", StringComparison.Ordinal))
                .OrderBy(f => f, StringComparer.Ordinal)
                .ToList();
        }

        private static List<string> CopiedFiles(string pattern)
        {
            return Directory.EnumerateFiles(CopyDir, pattern, SearchOption.AllDirectories)
                .Select(f => Path.GetRelativePath(CopyDir, f).Replace('\\', '/'))
                .OrderBy(f => f, StringComparer.Ordinal)
                .ToList();
        }

        /// <summary>Text without a BOM and with LF line ends, so a Windows checkout compares equal.</summary>
        private static string Normalized(string path)
        {
            return File.ReadAllText(path, Encoding.UTF8).TrimStart('\uFEFF').Replace("\r\n", "\n");
        }

        /// <summary>The GUID the script writes into the .meta of a copied file or folder.</summary>
        private static string ExpectedGuid(string relativePath)
        {
            return Convert.ToHexString(MD5.HashData(Encoding.UTF8.GetBytes("wildcat-protocol:" + relativePath))).ToLowerInvariant();
        }

        private static string GuidInMeta(string metaPath)
        {
            Assert.True(File.Exists(metaPath), $"{metaPath} is missing. {SyncHint}");
            var match = Regex.Match(File.ReadAllText(metaPath), @"^guid: ([0-9a-f]{32})\s*$", RegexOptions.Multiline);
            Assert.True(match.Success, $"{metaPath} has no guid line.");
            return match.Groups[1].Value;
        }

        [Fact]
        public void TheSdkCopyHasExactlyTheSharedSourceFiles()
        {
            Assert.True(Directory.Exists(CopyDir), $"{CopyDir} does not exist. {SyncHint}");
            var expected = SourceFiles();
            Assert.NotEmpty(expected);
            Assert.Equal(expected, CopiedFiles("*.cs"));
        }

        [Fact]
        public void EveryCopiedFileMatchesItsSource()
        {
            var stale = SourceFiles()
                .Where(f => File.Exists(Path.Combine(CopyDir, f)))
                .Where(f => Normalized(Path.Combine(SourceDir, f)) != Normalized(Path.Combine(CopyDir, f)))
                .ToList();
            Assert.True(stale.Count == 0, $"The SDK copy differs from the source in: {string.Join(", ", stale)}. {SyncHint}");
        }

        [Fact]
        public void ServerOnlyMessagesStayOutOfTheSdk()
        {
            Assert.True(Directory.Exists(Path.Combine(SourceDir, "ServerOnly")));
            Assert.False(Directory.Exists(Path.Combine(CopyDir, "ServerOnly")));
            foreach (var file in CopiedFiles("*.cs"))
            {
                string text = Normalized(Path.Combine(CopyDir, file));
                Assert.DoesNotContain("developerSecret", text);
                Assert.DoesNotContain("class SetPublisherDataRequest", text);
            }
        }

        [Fact]
        public void EveryCopiedFileAndFolderHasAStableUnityGuid()
        {
            Assert.Equal(ExpectedGuid(""), GuidInMeta(CopyDir + ".meta"));
            var folders = SourceFiles().Select(f => Path.GetDirectoryName(f)?.Replace('\\', '/'))
                .Where(d => !string.IsNullOrEmpty(d)).Distinct();
            foreach (var folder in folders)
                Assert.Equal(ExpectedGuid(folder), GuidInMeta(Path.Combine(CopyDir, folder) + ".meta"));
            foreach (var file in SourceFiles())
                Assert.Equal(ExpectedGuid(file), GuidInMeta(Path.Combine(CopyDir, file) + ".meta"));
            Assert.Equal(ExpectedGuid("README.md"), GuidInMeta(Path.Combine(CopyDir, "README.md.meta")));

            // No stray .meta files, and no two assets share a GUID.
            var metas = CopiedFiles("*.meta");
            Assert.Equal(SourceFiles().Count + folders.Count() + 1, metas.Count);
            var guids = metas.Select(m => GuidInMeta(Path.Combine(CopyDir, m))).Append(GuidInMeta(CopyDir + ".meta")).ToList();
            Assert.Equal(guids.Count, guids.Distinct().Count());
        }

        [Fact]
        public void TheCopyHasTheGeneratedNotice()
        {
            Assert.Equal(Normalized(Path.Combine(RepoRoot, "tools", "protocol-copy-readme.md")),
                Normalized(Path.Combine(CopyDir, "README.md")));
            var names = Directory.EnumerateFiles(CopyDir, "*", SearchOption.AllDirectories).Select(f => Path.GetFileName(f));
            Assert.DoesNotContain(names,
                f => !f.EndsWith(".cs", StringComparison.Ordinal) && !f.EndsWith(".meta", StringComparison.Ordinal) && f != "README.md");
        }

        [Fact]
        public void TheOldHandMaintainedSdkCopyIsGone()
        {
            Assert.False(File.Exists(Path.Combine(RepoRoot, "unity-sdk", "Assets", "Backend", "Plugins", "LowLevelAPI", "Messages.cs")));
        }

        [Fact]
        public void TheSdkCopyCompilesOnItsOwnAsCSharp9()
        {
            // Unity 6 compiles C# 9 at most, and the copy must not need anything from ServerOnly/.
            var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp9);
            var trees = CopiedFiles("*.cs").Select(f =>
                CSharpSyntaxTree.ParseText(File.ReadAllText(Path.Combine(CopyDir, f)), parseOptions, path: f)).ToList();
            var wanted = new HashSet<string> { "System.Private.CoreLib.dll", "System.Runtime.dll", "System.Collections.dll", "netstandard.dll" };
            var references = ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES"))
                .Split(Path.PathSeparator)
                .Where(p => wanted.Contains(Path.GetFileName(p)))
                .Select(p => MetadataReference.CreateFromFile(p));
            var compilation = CSharpCompilation.Create("ProtocolCopy", trees, references,
                new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Disable));

            var errors = compilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
            Assert.True(errors.Count == 0, string.Join(Environment.NewLine, errors.Select(e => e.ToString())));
        }

        [Fact]
        public void TheProtocolAssemblyTargetsNetStandard21()
        {
            var framework = typeof(WireCodec).Assembly.GetCustomAttributes(typeof(System.Runtime.Versioning.TargetFrameworkAttribute), false)
                .Cast<System.Runtime.Versioning.TargetFrameworkAttribute>().Single();
            Assert.Equal(".NETStandard,Version=v2.1", framework.FrameworkName);
            Assert.DoesNotContain(typeof(WireCodec).Assembly.GetReferencedAssemblies(),
                a => a.Name.StartsWith("Orleans", StringComparison.Ordinal) || a.Name.StartsWith("Microsoft.AspNetCore", StringComparison.Ordinal)
                     || a.Name.StartsWith("Newtonsoft", StringComparison.Ordinal));
        }
    }
}
